    else bytes.push(0xF0|(cp>>18),0x80|((cp>>12)&0x3F),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F));
  }
  return bytes.map(function(b){ return pad(b.toString(16).toUpperCase(),2); }).join(' ');
}
